;foreach(array('header','body','footer') as $part):$ps=$part_settings[$part]??array();$active=!isset($ps['active'])||!empty($ps['active']);$part_condition=$ps['condition']??'';?><td><a class="button button-small" href="<?php echo esc_url($base.$part);?>">Edit</a><label class="nb-part-control"><input type="checkbox" name="part_active_<?php echo esc_attr($part);?>" <?php checked($active);?>> Active</label><select name="part_condition_<?php echo esc_attr($part);?>" aria-label="<?php echo esc_attr(ucfirst($part).' display condition');?>"><option value="">All matching template pages</option><?php foreach(array('front_page'=>'Front Page','all_pages'=>'All Pages','all_posts'=>'All Posts','archive'=>'Archives','search'=>'Search Results','404'=>'404 Page','product'=>'Single Products','product_archive'=>'Product Archives','shop'=>'Shop','cart'=>'Cart','checkout'=>'Checkout') as $value=>$label):?><option value="<?php echo esc_attr($value);?>" <?php selected($part_condition,$value);?>><?php echo esc_html($label);?></option><?php endforeach;?></select></td><?php endforeach;?><td><button class="button button-small nirmaan-save-template-details" data-id="<?php echo esc_attr($t->ID);?>">Save Details</button> <button class="button button-small nirmaan-save-part-settings" data-id="<?php echo esc_attr($t->ID);?>">Save Sections</button> <button class="button button-small nirmaan-duplicate-template" data-id="<?php echo esc_attr($t->ID);?>">Duplicate</button> <button class="button button-small nirmaan-delete-template" data-id="<?php echo esc_attr($t->ID);?>">Delete</button></td></tr><?php endforeach;?></tbody></table><p class="nb-template-empty-filter" hidden>No templates match this search.</p></div><?php }
 private function condition_options($selected,$multiple=false){
  $selected=is_array($selected)?$selected:array($selected);
  $options=array('entire_site'=>'Entire Website','front_page'=>'Front Page','all_pages'=>'All Pages','all_posts'=>'All Posts','product'=>'Single Products','product_archive'=>'Product Archives','shop'=>'Shop','cart'=>'Cart','checkout'=>'Checkout','archive'=>'Archives','search'=>'Search Results','404'=>'404 Page');
  foreach($options as $value=>$label){
   $selected_attr=in_array($value,$selected,true)?' selected="selected"':'';
   echo '<option value="'.esc_attr($value).'"'.$selected_attr.'>'.esc_html($label).'</option>';
  }
 }
